WITH flattened AS (SELECT id, service, log_ts, level, status_code, key, value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) li AS key, value) SELECT level, service, PERCENTILE_APPROX(status_code, ARRAY(0.25, 0.5, 0.75)) AS status_code_quartiles, SORT_ARRAY(COLLECT_SET(key)) AS key_list, PERCENTILE_APPROX(status_code, ARRAY(0.25, 0.5, 0.75)) AS status_code_quartiles_2 FROM flattened GROUP BY 1, 2
